(() => {
const products=variables['f1e5b05b-d21f-44ef-8c3c-eb6e3a40d6ef']||[];
const result=variables['6a6bf395-1e42-407c-bd56-d7ad3036e31c']||{};
if(!result.guidance || !result.skin_type)return [];
const skin=String(result.skin_type).toLowerCase();
const types=new Set();
if(/tørr|dehydrat|dry/.test(skin))types.add('tørr');
if(/fet|oljete|talg|oily/.test(skin))types.add('fet');
if(/kombinasjon|kombinert|blandet|mixed/.test(skin))types.add('kombinert');
if(/sensitiv|følsom|sensitive/.test(skin))types.add('sensitiv');
if(/normal/.test(skin))types.add('normal');
const findings=(result.visible_findings||[]).join(' ').toLowerCase();
if(/sensitiv|irritert/.test(findings))types.add('sensitiv');
return products.filter(x=>(x.suitable_skin_types||[]).some(t=>types.has(String(t).toLowerCase()))).slice(0,4);
})()
